// Prop Agent — Highlights feed banner art, embedded as base64 (the GitHub
// snapshot push is UTF-8 text only). Served as image/jpeg: /api/banners?s=nba|nfl|pickem|pack|neon
const BANNERS = {"clashposter": "","grass": "", "packcut": "","neon": "","nba": "", "nfl": "", "pickem": "",
  "pack": ""};
module.exports = (req, res) => {
  const k = (req.query && req.query.s) || "nba";
  const b = BANNERS[k];
  if (!b) { res.status(404).end("unknown banner"); return; }
  res.setHeader("Content-Type", k === "packcut" ? "image/webp" : "image/jpeg");
  res.setHeader("Cache-Control", "public, max-age=86400, immutable");
  res.status(200).end(Buffer.from(b, "base64"));
};
